/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METCustTransListingController</c> controller
/// </summary>
class METCustActivityStatementController extends SrsPrintMgmtController//SrsPrintMgmtFormLetterController// SrsReportRunController //implements BatchRetryable
{
    METCustActivityStatementContract contract;

}

Method.Source:
/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METCustActivityStatementController construct()
{
    return new METCustActivityStatementController();
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Main method to run report
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    SrsReportRunController controller  = METCustActivityStatementController::construct();
    controller.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::METCustActivityStatement).getDefaultReportFormat());
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:CustActivityStatement");
    controller.startOperation();
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// setup print managment setup
/// </summary>
protected void initPrintMgmtReportRun()
{
    printMgmtReportRun = printMgmtReportRun::construct(
        PrintMgmtHierarchyType::Sales,
        PrintMgmtNodeType::Sales,
        PrintMgmtDocumentType::METCustActivityStatement);
    printMgmtReportRun.parmReportRunController(this);
    
    super();
}

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Run print mgmt report depending on metcusttrans accounts
    /// </summary>
    protected void runPrintMgmt()
    {
        METCustTable         custTable;
        QueryRun             queryRun;
        Query                custQuery;
        QueryBuildDataSource qbdsCust;
        List                 legalEntityList, associatedAccList;
        ListEnumerator       enumeratorLegalEntity, enumeratorAssAcc;

        
        contract = this.parmReportContract().parmRdpContract();

        //To query METCustTrans find unique customer account and pass it to DP class to run report
        
        custQuery = new Query();
        qbdsCust = custQuery.addDataSource(tableNum(METCustTable));
        
        // Add selections fields
        qbdsCust.addSelectionField(fieldnum(METCustTable, CSLegalEntity));
        qbdsCust.addSelectionField(fieldnum(METCustTable, CSAccountNum));

        // Apply filters - if empty list ignore filter
        legalEntityList     = new List(Types::String);
        associatedAccList   = new List(Types::String);

        legalEntityList = contract.parmLegalEntity();
        associatedAccList = contract.parmAccountNum();

        if(!legalEntityList.empty())
        {
            enumeratorLegalEntity = legalEntityList.getEnumerator();
            enumeratorLegalEntity.reset();
            while(enumeratorLegalEntity.moveNext())
            {
                qbdsCust.addRange(fieldNum(METCustTable, CSLegalEntity)).value(enumeratorLegalEntity.current());
            }
        }

        if (!associatedAccList.empty())
        {
            enumeratorAssAcc = associatedAccList.getEnumerator();
            enumeratorAssAcc.reset();
            while(enumeratorAssAcc.moveNext())
            {
                qbdsCust.addRange(fieldNum(METCustTable, CSAccountNum)).value(enumeratorAssAcc.current());
            }
        }

        if (custQuery)
        {
            queryRun = new QueryRun(custQuery);

            if(!queryRun.next())
            {
                throw error ("@SYS26348");
            }
            do
            {
                custTable = queryRun.get(tableNum(METCustTable));
                
                contract.parmCSAccountNum(custTable.CSAccountNum);
                contract.parmCSLegalEntity(custTable.CSLegalEntity);
                
                //If print managment param is true
                if (contract.parmUsePrintManagement())
                {
                    this.initPrintMgmtReportRun();
                }
                else
                {
                    //use ssrs param printing
                    SRSPrintDestinationSettings pds = this.parmReportContract().parmPrintSettings();
                    PrintMgmtReportRun printMgmtReportRunInstance = printMgmtReportRun;
                    printMgmtReportRunInstance.parmDefaultOriginalPrintJobSettings(pds);

                    // Force the use of the print settings selected on the report dialog.
                    printMgmtReportRunInstance.parmForcePrintJobSettings(true);
                }

                printMgmtReportRun.load(custTable,
                                        custTable,
                                        CompanyInfo::languageId());

                this.outputReports();

            } while (queryRun.next());
        }
    }
